import {
  Native2,
  makeConnection2,
  makeClient2
} from "../chunks/repository-cache-tyytaxap.js";

// src/database/sqlite.node.ts
import { DatabaseSync } from "node:sqlite";
import { Context, Effect, Layer } from "effect";
import { Reactivity } from "effect/reactivity";
import { SqlClient } from "effect/sql";
import { classifySqliteError, SqlError } from "effect/sql/SqlError";
var TypeId = "~@opencode/core/database/SqliteNode";
var supportsTuningPragmas = true;
var supportsForeignKeyToggle = true;
var make = (options) => Effect.gen(function* () {
  const native = yield* Native2;
  const run = (query, params = []) => Effect.withFiber((fiber) => {
    const statement = native.prepare(query);
    statement.setReadBigInts(Context.get(fiber.context, SqlClient.SafeIntegers));
    try {
      return Effect.succeed(statement.all(...params));
    } catch (cause) {
      return Effect.fail(new SqlError({
        reason: classifySqliteError(cause, { message: "Failed to execute statement", operation: "execute" })
      }));
    }
  });
  const runValues = (query, params = []) => Effect.withFiber((fiber) => {
    const statement = native.prepare(query);
    statement.setReadBigInts(Context.get(fiber.context, SqlClient.SafeIntegers));
    statement.setReturnArrays(true);
    try {
      return Effect.succeed(statement.all(...params));
    } catch (cause) {
      return Effect.fail(new SqlError({
        reason: classifySqliteError(cause, { message: "Failed to execute statement", operation: "execute" })
      }));
    }
  });
  const connection = makeConnection2(run, runValues, {
    loadExtension: (path) => Effect.try({
      try: () => native.loadExtension(path),
      catch: (cause) => new SqlError({
        reason: classifySqliteError(cause, { message: "Failed to load extension", operation: "loadExtension" })
      })
    })
  });
  return yield* makeClient2(options, connection, TypeId, (acquirer) => ({
    loadExtension: (path) => Effect.flatMap(acquirer, (_) => _.loadExtension(path))
  }));
});
var nativeLayer = (config) => Layer.effect(Native2, Effect.gen(function* () {
  const native = new DatabaseSync(config.filename, {
    readOnly: config.readonly,
    timeout: config.timeout,
    allowExtension: config.allowExtension,
    enableForeignKeyConstraints: true,
    open: true
  });
  yield* Effect.addFinalizer(() => Effect.sync(() => native.close()));
  if (config.disableWAL !== true && config.readonly !== true)
    native.exec("PRAGMA journal_mode = WAL;");
  return native;
}));
var clientLayer = (config) => Layer.effect(SqlClient.SqlClient, make(config));
var sqliteLayer = (config) => {
  const native = nativeLayer(config);
  return Layer.merge(native, clientLayer(config).pipe(Layer.provide(native))).pipe(Layer.provide(Reactivity.layer));
};
export {
  sqliteLayer,
  supportsForeignKeyToggle,
  supportsTuningPragmas
};
